<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $items = DB::table("order_items")->get(); foreach($items as $i) { $var = DB::table("product_variations")->where("id", $i->product_variation_id)->first(); if(!$var) { $newVarId = DB::table("product_variations")->insertGetId(["product_id" => $i->product_variation_id, "price" => $i->unit_price, "created_at" => now(), "updated_at" => now()]); DB::table("order_items")->where("id", $i->id)->update(["product_variation_id" => $newVarId]); echo "Fixed item " . $i->id . "\n"; } }
